#endif

// Signed distance for an upright equilateral triangle centered at origin
// This matches the reference-style sdEquilateralTriangle_Centered from Inigo Quilez
inline float sdEquilateralTriangle_Centered(float2 p, float r)
{
    float k = 1.7320508; // sqrt(3)
    p.x = abs(p.x) - r;
    p.y = p.y + r / k;
    if (p.x + k * p.y > 0.0)
        p = float2(p.x - k * p.y, -k * p.x - p.y) * 0.5;
    p.x -= clamp(p.x, -2.0 * r, 0.0);
    return -length(p) * (p.y < 0.0 ? -1.0 : 1.0);
}

// User request: A filled equilateral triangle pointing upwards and centered on the screen, with adjustable size and smooth edges.
void FunctionName_float(float2 UV, float Size, float4 Color, out float4 outColor)
{
    // PLAN:
    // 1) Recenter UV to origin and scale by Size so 0.5 = half-screen triangle.
    // 2) Use an upright equilateral triangle SDF (centered at origin, pointing up).
    // 3) Apply smoothstep on the SDF for anti-aliased edges.
    // 4) Use the result as both RGB multiplier and alpha for a solid colored triangle.

    // 1) Center UV coordinates and scale by Size (0.5 ≈ half-screen triangle)
    float2 centered = UV - float2(0.5, 0.5);
    float safeSize = max(Size, 1e-4);
    centered /= safeSize;

    // 2) Triangle SDF (equilateral, centered, pointing upwards)
    float radius = 1.0; // base radius in this normalized space
    float dist = sdEquilateralTriangle_Centered(centered, radius);

    // 3) Anti-aliased edge using a small fixed transition width
    float edge = smoothstep(0.01, -0.01, dist);

    // 4) Output with smooth alpha (single fill color)
    float alpha = edge;
    outColor = float4(Color.rgb * alpha, alpha);
}
