// Signed distance to a regular hexagon centered at origin
// radius = distance from center to vertices
// Negative inside, positive outside
float sdRegularHexagon(float2 p, float radius)
{
    // Inigo Quilez hexagon SDF in canonical space (radius = 1)
    const float k = 0.5773502691896258; // 1 / sqrt(3)
    const float k2 = 1.7320508075688772; // sqrt(3)

    p = abs(p);
    float2 q = float2(p.x - k * p.y, p.y * k2);
    float2 w = float2(max(q.x, 0.0), max(q.y, 0.0));
    float d = length(w);
    d += min(0.0, max(q.x, q.y));

    // Scale from unit hex to requested radius
    return d * radius;
}

void FunctionName_float(float2 UV, float Size, float Rotation, float4 Color, out float4 outColor)
{
    // Center UV so (0.5,0.5) is origin
    float2 p = UV - 0.5;

    // Make hex size roughly match Size as vertex radius in UV space
    float radius = max(Size, 1e-4);

    // Rotate in UV space around the center
    p = rotate2D(p, Rotation);

    // Compute signed distance to hexagon of given radius
    float dist = sdRegularHexagon(p, radius);

    // Pixel-size-dependent antialiasing for crisp edges
    float2 grad = float2(ddx(dist), ddy(dist));
    float pixelWidth = max(1e-4, length(grad));

    // Inside if dist < 0; transition over one pixel
    float alpha = smoothstep(pixelWidth, -pixelWidth, dist);

    // Solid fill color with alpha mask
    outColor = float4(Color.rgb, alpha) * alpha;
}
