{
    float2 d = abs(p) - b;
    float2 dMax = float2(max(d.x, 0.0), max(d.y, 0.0));
    return length(dMax) + min(max(d.x, d.y), 0.0);
}

inline float opUnion(float d1, float d2)
{
    return min(d1, d2);
}

inline float opIntersection(float d1, float d2)
{
    return max(d1, d2);
}

inline float opSubtract(float d1, float d2)
{
    return max(d1, -d2);
}

inline float2 rotate2D(float2 p, float angle)
{
    float c = cos(angle);
    float s = sin(angle);
    return float2(c * p.x - s * p.y, s * p.x + c * p.y);
}

void FunctionName_float(float2 UV, float Size, float Sharpness, float4 Color, out float4 outColor)
{
    // User request: A simple four-pointed star centered on the screen with adjustable size and point sharpness, single fill color.

    // PLAN:
    // 1) Map UV to centered coordinates around (0.5, 0.5) and scale by Size.
    // 2) Build a diamond (rotated box) SDF for the up/down points.
    // 3) Build a cross-shaped SDF (intersection of horizontal & vertical rectangles) for left/right width control.
    // 4) Combine these with union to form a simple four-pointed star.
    // 5) Use Sharpness to interpolate between a fat cross and a sharp diamond.
    // 6) Apply smoothstep for anti-aliasing and output Color with alpha mask.

    // 1) Center UV coordinates and scale by Size (0.5 ~ half screen)
    float2 centered = UV - 0.5;
    float safeSize = max(Size, 1e-4);
    centered /= safeSize;

    // 2) Diamond for up/down points (rotated square)
    float2 pDiamond = rotate2D(centered, PI * 0.25);
    // Base half-size of the diamond; controls overall point length vertically
    float baseHalf = 0.7;
    float dDiamond = sdBox(pDiamond, float2(baseHalf, baseHalf));

    // 3) Cross shape for left/right width: intersection of horizontal & vertical rectangles
    // Horizontal bar
    float barThicknessBase = 0.25;
    // Sharpness in [0,1]: 0 = wide/fat, 1 = thin/sharp
    float sharpT = saturate(Sharpness);
    float barThickness = lerp(barThicknessBase, barThicknessBase * 0.3, sharpT);

    float2 halfSizeH = float2(1.0, barThickness);
    float2 halfSizeV = float2(barThickness, 1.0);

    float dH = sdBox(centered, halfSizeH);
    float dV = sdBox(centered, halfSizeV);

    float dCross = opIntersection(dH, dV);

    // 4) Combine diamond and cross with union
    float dCombined = opUnion(dDiamond, dCross);

    // 5) Smooth edge (AA). Negative inside, positive outside.
    float edge = smoothstep(0.01, -0.01, dCombined);

    // 6) Output color with alpha = coverage mask
    outColor = float4(Color.rgb * edge, edge);
}
