// Signed distance to a 4-pointed star (like a rotated plus),
// constructed by taking the max of two stretched diamonds.
inline float sdFourPointStar(float2 p, float pointLen, float coreRadius, float pointSharpness)
{
    // pointLen: how far the tips extend from center
    // coreRadius: size of the central "core" area
    // pointSharpness: 0 = very wide base, 1 = very narrow base

    // Clamp inputs to safe ranges
    pointLen      = max(pointLen, 1e-4);
    coreRadius    = max(coreRadius, 1e-4);
    pointSharpness = saturate(pointSharpness);

    // Base width of the arms at the center.
    // As sharpness increases, this gets smaller.
    float baseWidth = lerp(coreRadius, coreRadius * 0.2, pointSharpness);

    // Build an axis-aligned diamond (|x| + |y| <= r) stretched differently on x/y
    // to get vertical tips, then rotate by 90 degrees for horizontal tips.

    // Vertical arms diamond (up/down)
    float2 pv = p;
    // Scale so that vertical extent reaches pointLen, horizontal set by baseWidth
    float2 scaleV = float2(baseWidth, pointLen);
    pv /= scaleV;
    float dv = (abs(pv.x) + abs(pv.y)) - 1.0; // diamond SDF in scaled space
    dv *= max(scaleV.x, scaleV.y); // approximate rescale of distance

    // Horizontal arms diamond (left/right) – swap scale components
    float2 ph = p;
    float2 scaleH = float2(pointLen, baseWidth);
    ph /= scaleH;
    float dh = (abs(ph.x) + abs(ph.y)) - 1.0;
    dh *= max(scaleH.x, scaleH.y);

    // Union of these two diamonds gives a four-pointed star.
    float dStar = min(dv, dh);

    // Small circular core to keep a rounded center, blended with min.
    float dCore = length(p) - coreRadius;
    dStar = min(dStar, dCore);

    return dStar;
}

void FunctionName_float(float2 UV, float Size, float Sharpness, float4 Color, out float4 outColor)
{
    // Center and scale UV to a -1..1 space based on Size
    float2 p = UV - 0.5;
    float safeSize = max(Size, 1e-4);
    p /= safeSize;

    // Map Sharpness [0,1] to both point length and tip width behavior.
    float s = saturate(Sharpness);

    // Point length: longer as sharpness increases
    float pointLen   = lerp(0.8, 1.4, s);
    // Core radius: slightly smaller for sharper stars
    float coreRadius = lerp(0.35, 0.2, s);

    float d = sdFourPointStar(p, pointLen, coreRadius, s);

    // Anti-aliased edge
    float pixel = fwidth(d);
    float edge = smoothstep(0.0, -pixel, d);

    outColor = float4(Color.rgb * edge, edge);
}
